import numpy as np
import pandas as pd
from scipy import stats

def r_tidy(x, **kwargs):
    """
    Tidy method for hypothesis test and model objects.
    Handles lm (linear model) objects primarily.
    """

    # Handle linear model objects
    if hasattr(x, '__class__') and 'lm' in str(type(x).__name__).lower():
        return _tidy_lm(x, **kwargs)

    # Handle generic objects with estimate, statistic, p.value, parameter
    if isinstance(x, dict):
        return _tidy_htest(x, **kwargs)

    return pd.DataFrame()


def _tidy_lm(model, conf_int=False, conf_level=0.95, **kwargs):
    """Tidy a linear model (lm) object."""

    # Extract coefficients, standard errors, t-statistics, and p-values
    # These are typically stored in model.summary or similar

    if not hasattr(model, 'coefficients'):
        return pd.DataFrame()

    coef = model.coefficients

    # Get standard errors
    if hasattr(model, 'residuals'):
        residuals = model.residuals
        n = len(residuals)
        p = len(coef)
        dof = n - p
        mse = np.sum(residuals**2) / dof

        # Calculate standard errors from the model
        if hasattr(model, 'vcov'):
            se = np.sqrt(np.diag(model.vcov))
        else:
            se = np.full_like(coef, np.nan)
    else:
        se = np.full_like(coef, np.nan)
        dof = np.nan

    # Calculate t-statistics
    t_stats = coef / se

    # Calculate p-values
    if np.isfinite(dof):
        p_values = 2 * (1 - stats.t.cdf(np.abs(t_stats), dof))
    else:
        p_values = np.full_like(coef, np.nan)

    # Get term names
    if hasattr(model, 'term_names'):
        terms = model.term_names
    else:
        terms = ['(Intercept)'] + [f'x{i}' for i in range(1, len(coef))]

    # Build result dataframe
    result = pd.DataFrame({
        'term': terms,
        'estimate': coef,
        'std.error': se,
        'statistic': t_stats,
        'p.value': p_values
    })

    # Add confidence interval if requested
    if conf_int:
        alpha = 1 - conf_level
        t_crit = stats.t.ppf(1 - alpha/2, dof)
        margin = t_crit * se
        result['conf.low'] = coef - margin
        result['conf.high'] = coef + margin

    return result


def _tidy_htest(x, **kwargs):
    """Tidy a hypothesis test object (htest)."""

    ret = {}

    # Extract basic fields
    if 'estimate' in x:
        estimate = x['estimate']
        if np.isscalar(estimate):
            ret['estimate'] = estimate
        else:
            # Multiple estimates
            for i, est in enumerate(estimate, 1):
                ret[f'estimate{i}'] = est

    if 'statistic' in x:
        ret['statistic'] = x['statistic']

    if 'p.value' in x:
        ret['p.value'] = x['p.value']

    if 'parameter' in x and x['parameter'] is not None:
        param = x['parameter']
        if np.isscalar(param):
            ret['parameter'] = param
        elif isinstance(param, dict):
            ret.update(param)

    # Add confidence interval if present
    if 'conf.int' in x and x['conf.int'] is not None:
        conf = x['conf.int']
        ret['conf.low'] = conf[0]
        ret['conf.high'] = conf[1]

    # Add method if present
    if 'method' in x and x['method'] is not None:
        ret['method'] = str(x['method']).strip()

    # Add alternative if present
    if 'alternative' in x and x['alternative'] is not None:
        ret['alternative'] = str(x['alternative'])

    # Convert to dataframe (single row)
    result = pd.DataFrame([ret])

    return result
